## Why This Is Asked

This question tests understanding of order statistics in dynamic sets, along with practical implementation details like lazy deletion and handling duplicates.

## Key Concepts

- **Median of a dynamic set**: the middle element (or average of two middle elements) when sorted
- **Two-heap approach**: max-heap for the lower half, min-heap for the upper half
- **Lazy deletion**: defer actual removal until top operations, tracking deletions via a count map
- **Duplicate handling**: maintain frequency counts rather than storing duplicate values multiple times in the heaps

## Code Example

```javascript
class MedianFinder {
  constructor() {
    this.low = new MaxHeap();    // max-heap for lower half
    this.high = new MinHeap();   // min-heap for upper half
    this.delayed = new Map();    // lazy deletion map
  }

  insert(num) {
    if (this.low.isEmpty() || num <= this.low.peek()) {
      this.low.push(num);
    } else {
      this.high.push(num);
    }
    this.rebalance();
  }

  rebalance() {
    if (this.low.size() > this.high.size() + 1) {
      this.high.push(this.low.pop());
    } else if (this.high.size() > this.low.size()) {
      this.low.push(this.high.pop());
    }
  }

  erase(num) {
    this.delayed.set(num, (this.delayed.get(num) || 0) + 1);
    if (num <= this.low.peek()) {
      this.low.deleted++;
    } else {
      this.high.deleted++;
    }
    this.rebalance();
  }

  getMedian() {
    this.prune(this.low);
    this.prune(this.high);
    if (this.low.size() > this.high.size()) {
      return this.low.peek();
    }
    return (this.low.peek() + this.high.peek()) / 2;
  }
}
```

## Why This Is Asked
Tests ability to design a dynamic string structure supporting weighted, prefix-based queries and order-statistics. A Trie augmented with per-node aggregates enables efficient prefix sums and k-th retrieval while handling duplicates via cumulative weights.

## Key Concepts
- Trie with per-node aggregates (subtreeWeight, terminalWeight)
- O(len(word)) time complexity for insert/erase operations
- O(len(prefix)) for prefix-sum queries
- O(len(prefix) + len(target_word)) for kth-word queries
- Duplicate handling via cumulative weight values

## Code Example
```javascript
class WeightedTrie {
  constructor() {
    this.root = new TrieNode();
  }

  insertWord(word, w) {
    let node = this.root;
    for (const char of word) {
      const idx = char.charCodeAt(0) - 97;
      if (!node.children[idx]) node.children[idx] = new TrieNode();
      node = node.children[idx];
      node.subtreeWeight += w;
    }
    node.terminalWeight += w;
  }

  eraseWord(word, w) {
    this.insertWord(word, -w);
  }

  queryPrefixSum(prefix) {
    let node = this.traverse(prefix);
    return node ? node.subtreeWeight : 0;
  }

  kthWordWithPrefix(prefix, k) {
    let node = this.traverse(prefix);
    if (!node || node.subtreeWeight < k) return null;
    let word = prefix;
    while (!node.terminalWeight) {
      for (let i = 0; i < 26; i++) {
        if (!node.children[i]) continue;
        if (node.children[i].subtreeWeight >= k) {
          word += String.fromCharCode(97 + i);
          node = node.children[i];
          break;
        }
        k -= node.children[i].subtreeWeight;
      }
    }
    return word;
  }

  traverse(prefix) {
    let node = this.root;
    for (const char of prefix) {
      const idx = char.charCodeAt(0) - 97;
      if (!node.children[idx]) return null;
      node = node.children[idx];
    }
    return node;
  }
}

class TrieNode {
  constructor() {
    this.children = new Array(26).fill(null);
    this.subtreeWeight = 0;
    this.terminalWeight = 0;
  }
}
```

